export function OrbitingWordsTailwind() {
  const tags = ["React 19", "TypeScript", "Motion 14", "CSS Modules"];
  return (
    <div className="relative flex h-52 w-full items-center justify-center">
      <span className="z-10 rounded-full border border-zinc-700 bg-zinc-900 px-4 py-1.5 text-sm font-semibold text-zinc-100">
        MotionFoundry Core
      </span>
      {tags.map((t, i) => {
        const a = (i / tags.length) * Math.PI * 2;
        return (
          <span
            key={t}
            style={{ transform: `translate(${Math.cos(a) * 105}px, ${Math.sin(a) * 62}px)` }}
            className="absolute rounded border border-zinc-800 bg-zinc-950 px-2 py-0.5 font-mono text-[11px] text-zinc-400"
          >
            {t}
          </span>
        );
      })}
    </div>
  );
}
